test('scribe career can branch into archive mastery without becoming envoy',()=>{const {run}=game();run(setup+'s.age=30;s.prestige=80;s.experience.state=40;s.skills.literacy=100;s.skills.speech=100;window.__m=careerContact("scribe")');for(const [id,ch] of [['scribe_offer',0],['scribe_copy',1],['scribe_record_dispute',1],['scribe_secret_record',0],['scribe_envoy_list',1],['scribe_archive_mastery',0]])run(`s.pendingEventId="${id}";s.pendingEventContext={age:s.age,year:s.year+s.age,month:1,targetId:__m.id};chooseContextEvent(${ch})`);assert.equal(run('s.storyArcs.scribe.status'),'completed');assert.equal(run('s.role'),'Bitigçi');});
