test('bard career grows from mentor to a delayed legacy song',()=>{const {run}=game();run(setup+'s.age=30;s.prestige=80;s.experience.culture=20;s.skills.speech=100;window.__m=careerContact("bard")');for(const id of ['bard_mentor_offer','bard_first_toy','bard_rival_verse','bard_patron_offer','bard_legacy_song'])run(`s.pendingEventId="${id}";s.pendingEventContext={age:s.age,year:s.year+s.age,month:1,targetId:__m.id};chooseContextEvent(0)`);assert.equal(run('s.storyArcs.bardcareer.status'),'completed');assert.ok(run('s.delayedEvents.some(x=>x.eventId==="bard_old_song_returns")'));});
