test('boy council rise keeps the same patron and rival through promotion',()=>{const {run}=game();run(setup+'s.age=32;s.health=100;s.wealth=200;s.skill=100;s.prestige=90;s.experience.state=60;Object.keys(s.skills).forEach(k=>s.skills[k]=100);window.__pair=eventTargetSelections("statePair","bey_request")[0];window.__patron=__pair.target;window.__rival=__pair.other');for(const [id,ch] of [['bey_request',0],['council_pasture_case',0],['council_levy_choice',0],['council_rival_challenge',0],['council_support_test',0]])run(`window.__e=EVENT_DECK.find(x=>x.id==="${id}");window.__sel=eventTargetSelections(__e.target,__e.id)[0];if(__sel.target.id!==__patron.id||__sel.other.id!==__rival.id)throw Error("state pair drift");s.pendingEventId=__e.id;s.pendingEventContext={age:s.age,year:s.year+s.age,month:1,targetId:__sel.target.id,otherTargetId:__sel.other.id};chooseContextEvent(${ch})`);assert.equal(run('s.storyArcs.councilrise.nextEventId'),'council_bey_nomination');assert.equal(run('eventRequirementOK(EVENT_DECK.find(x=>x.id==="council_bey_nomination"))'),true);run('window.__e=EVENT_DECK.find(x=>x.id==="council_bey_nomination");window.__sel=eventTargetSelections(__e.target,__e.id)[0];s.pendingEventId=__e.id;s.pendingEventContext={age:s.age,year:s.year+s.age,month:2,targetId:__sel.target.id,otherTargetId:__sel.other.id};chooseContextEvent(0)');assert.equal(run('s.role'),'Boy Beyi');assert.equal(run('s.storyArcs.councilrise.status'),'completed');});
test('boy bey role is locked behind council influence and trust even when skills are high',()=>{const {run}=game();run(setup+'s.age=32;s.skill=100;s.prestige=90;s.experience.state=60;Object.keys(s.skills).forEach(k=>s.skills[k]=100);s.stateCourt={initialized:true,influence:0,councilTrust:30,tribeSupport:45,rivalPressure:30,obligations:0,decisions:[]}');assert.ok(run('careerIssue(D.careers.find(r=>r.id==="bey")).includes("nüfuzu")'));run('s.stateCourt.influence=25;s.stateCourt.councilTrust=20');assert.ok(run('careerIssue(D.careers.find(r=>r.id==="bey")).includes("güveni")'));run('s.stateCourt.councilTrust=40');assert.equal(run('careerIssue(D.careers.find(r=>r.id==="bey"))'),'');});
test('beylik decisions schedule a judgment that returns years later',()=>{const {run}=game();run(setup+'s.age=36;s.health=100;s.wealth=200;s.skill=100;s.prestige=90;s.experience.state=60;Object.keys(s.skills).forEach(k=>s.skills[k]=100);ensureStateCircle();s.stateCourt.influence=70;s.stateCourt.councilTrust=70;s.role="Boy Beyi";window.__pair=eventTargetSelections("statePair","bey_first_petition")[0]');for(const [id,ch] of [['bey_first_petition',0],['bey_winter_reserve',0],['bey_kin_request',0],['bey_border_agreement',0]])run(`window.__e=EVENT_DECK.find(x=>x.id==="${id}");window.__sel=eventTargetSelections(__e.target,__e.id)[0];s.pendingEventId=__e.id;s.pendingEventContext={age:s.age,year:s.year+s.age,month:1,targetId:__sel.target.id,otherTargetId:__sel.other.id};chooseContextEvent(${ch})`);assert.equal(run('s.storyArcs.beyrule.nextEventId'),'bey_old_judgment');assert.ok(run('s.delayedEvents.some(x=>x.eventId==="bey_old_judgment"&&x.status==="pending")'));run('window.__d=s.delayedEvents.find(x=>x.eventId==="bey_old_judgment"&&x.status==="pending");s.age=__d.dueYear-s.year;window.__e=EVENT_DECK.find(x=>x.id==="bey_old_judgment");window.__sel=eventTargetSelections(__e.target,__e.id)[0];s.pendingEventId=__e.id;s.pendingEventContext={age:s.age,year:s.year+s.age,month:1,targetId:__sel.target.id,otherTargetId:__sel.other.id,delayedId:__sel.delayed.id,delayedPayload:__sel.delayed.payload};chooseContextEvent(1)');assert.equal(run('s.storyArcs.beyrule.status'),'completed');assert.equal(run('s.delayedEvents.find(x=>x.id===__d.id).status'),'resolved');});
test('state work and yearly ticks evolve influence and rival pressure',()=>{const {run}=game();run(setup+'s.age=34;s.role="Boy Beyi";s.health=100;s.skill=100;s.prestige=90;s.experience.state=60;Object.keys(s.skills).forEach(k=>s.skills[k]=100);ensureStateCircle();s.stateCourt.influence=30;s.stateCourt.councilTrust=45;s.stateCourt.rivalPressure=30;window.__before=s.stateCourt.influence;workRole()');assert.ok(run('s.stateCourt.influence>=__before'));run('window.__rp=s.stateCourt.rivalPressure;stateYearTick()');assert.ok(run('s.stateCourt.rivalPressure>=0&&s.stateCourt.rivalPressure<=100'));});
