test('healing story follows the same healer through recovery',()=>{const {run}=game();run(setup+'s.age=30;s.health=70;s.wealth=30;acquireAilment("fever",{severity:2,duration:3,source:"test"});s.flags.health_crisis_ready=true;window.__e=EVENT_DECK.find(e=>e.id==="health_crisis");window.__sel=eventTargetSelections(__e.target,__e.id)[0];window.__h=__sel.target;s.pendingEventId=__e.id;s.pendingEventContext={age:s.age,year:s.year+s.age,month:1,targetId:__h.id};chooseContextEvent(1)');assert.equal(run('s.storyArcs.healingroad.nextEventId'),'health_followup');assert.ok(run('s.healthProfile.healerVisits>=1'));run('window.__e=EVENT_DECK.find(e=>e.id==="health_followup");window.__sel=eventTargetSelections(__e.target,__e.id)[0]');assert.equal(run('__sel.target.id'),run('__h.id'));});
test('battle wound creates serious ailment scar and a years-later flare',()=>{const {run}=game();run(setup+'s.age=30;s.military.served=true;s.military.active=true;s.health=100;s.pendingEventId="battle_wound";s.pendingEventContext={age:s.age,year:s.year+s.age,month:1};chooseContextEvent(1)');assert.ok(run('s.ailments.some(x=>x.id==="deep_wound"&&x.severity===3)'));assert.ok(run('s.healthProfile.scars.some(x=>x.kind==="battle"&&x.severity===2)'));assert.ok(run('s.delayedEvents.some(x=>x.eventId==="old_wound_flare"&&x.status==="pending")'));assert.ok(run('physicalHealthIssue({kind:"training",id:"wrestling"}).length>0'));});
