test('asset prices react to market state and buying records persistent condition',()=>{const {run}=game();run(setup+'s.age=25;s.economy.marketIndex=80;s.economy.tradeDemand=30;s.economy.foodPressure=20;window.__low=assetBuyPrice("flock");s.economy.marketIndex=140;s.economy.foodPressure=90;window.__high=assetBuyPrice("flock")');assert.ok(run('__high>__low'));run('s.economy.marketIndex=100;s.economy.foodPressure=25;s.wealth=200;s.monthsRemaining=12;window.__p=assetBuyPrice("flock");buyAsset("flock")');assert.equal(run('s.wealth'),run('200-__p'));assert.ok(run('s.economy.assetState.flock.condition>=80'));});
