test('fresh lives have romance appearance education mobility yearly ambition and persistent variety profiles',()=>{const {run}=game();assert.equal(run('s.version'),13);assert.ok(run('s.variety&&s.variety.ambition&&s.variety.ambition.target>0'));assert.equal(run('s.variety.ambition.year'),run('s.year+s.age'));});
test('variety ambition counts distinct meaningful actions instead of repeated spam',()=>{const {run}=game();run(setup+'s.age=20;s.variety={activityStats:{},recent:[],completed:[],annualHistory:[],rerolls:0,ambition:{id:"variety",title:"Test",desc:"",target:5,progress:0,year:s.year+s.age,done:false,keys:[],reward:{}}};trackLifeVarietyAction({kind:"period",id:"market"});trackLifeVarietyAction({kind:"period",id:"market"});trackLifeVarietyAction({kind:"training",id:"horse"})');assert.equal(run('s.variety.ambition.progress'),2);});
test('seasonal activities rotate with the calendar month',()=>{const {run}=game();run(setup+'s.age=20;s.monthsRemaining=10');assert.ok(run('seasonalActivitiesNow().some(x=>x.id==="spring_move")'));run('s.monthsRemaining=5');assert.ok(run('seasonalActivitiesNow().some(x=>x.id==="autumn_store")'));assert.ok(run('!seasonalActivitiesNow().some(x=>x.id==="spring_move")'));});
test('repeating the same period activity is remembered and loses novelty',()=>{const {run}=game();run(setup+'s.age=20;s.variety.recent=[{key:"period:bardlisten",year:s.year+s.age,month:1},{key:"period:bardlisten",year:s.year+s.age,month:2},{key:"period:bardlisten",year:s.year+s.age,month:3}];window.__h=s.happiness;window.__note=periodNoveltyBonus("bardlisten")');assert.ok(run('__note.includes("tekrarlamak")'));assert.equal(run('s.happiness'),run('__h-1'));});
test('v8 saves migrate to v13 with variety profile and dedicated backup',()=>{const {run,storage}=game();run('s.version=8;delete s.variety;save();load()');assert.equal(run('s.version'),13);assert.ok(storage.has('yazgi_before_v13'));assert.ok(run('s.variety&&s.variety.activityStats&&s.variety.ambition'));});
test('migration destinations expose other settlements available in the current year',()=>{const {run}=game();run(setup+'s.age=20;ensureMobility()');assert.ok(run('migrationDestinations().some(x=>x.place!==s.place)'));assert.ok(run('migrationDestinations().every(x=>realmActiveAt(x.realm,s.year+s.age))'));});
test('household migration moves partner and children while preserving tribe identity',()=>{const {run}=game();run(setup+'s.age=25;s.wealth=200;s.partner=normalizeNPC({name:"Es",gender:"female",age:24,alive:true,rel:80,type:"Eş"});s.children=[normalizeNPC({name:"Cocuk",gender:"male",age:4,alive:true,rel:85,type:"Çocuk"})];window.__tribe=s.tribe;window.__dest=migrationDestinations().find(x=>x.realm===s.realm)||migrationDestinations()[0];Math.random=()=>.999;migrateTo(__dest.realm,__dest.place,"household")');assert.equal(run('s.place'),run('__dest.place'));assert.equal(run('s.tribe'),run('__tribe'));assert.equal(run('s.partner.place'),run('__dest.place'));assert.equal(run('s.children[0].place'),run('__dest.place'));assert.equal(run('s.mobility.moves'),1);});
test('moving alone leaves close family behind and strains the relationship',()=>{const {run}=game();run(setup+'s.age=25;s.wealth=200;s.partner=normalizeNPC({name:"Es",gender:"female",age:24,alive:true,rel:80,type:"Eş",place:s.place,realm:s.realm});window.__rel=s.partner.rel;window.__old=s.place;window.__dest=migrationDestinations().find(x=>x.realm===s.realm);Math.random=()=>.999;migrateTo(__dest.realm,__dest.place,"alone")');assert.equal(run('s.partner.place'),run('__old'));assert.ok(run('s.partner.rel<__rel'));});
test('cross realm migration reduces old political influence but does not rewrite tribe',()=>{const {run}=game();run(setup+'s.age=70;s.wealth=300;ensureStateCourt();s.stateCourt.influence=80;s.stateCourt.councilTrust=70;window.__tribe=s.tribe;window.__dest=migrationDestinations().find(x=>x.realm!==s.realm);Math.random=()=>.999');assert.ok(run('!!__dest'));run('migrateTo(__dest.realm,__dest.place,"alone")');assert.equal(run('s.tribe'),run('__tribe'));assert.ok(run('s.stateCourt.influence<=20'));});
test('v9 saves migrate to v13 with mobility profile and dedicated backup',()=>{const {run,storage}=game();run('s.version=9;delete s.mobility;save();load()');assert.equal(run('s.version'),13);assert.ok(storage.has('yazgi_before_v13'));assert.ok(run('s.mobility&&Array.isArray(s.mobility.history)&&Number.isFinite(s.mobility.localStanding)'));});
test('studying a path creates a persistent mentor peer group and progress',()=>{const {run}=game();run(setup+'s.age=18;s.monthsRemaining=12;studyEducation("smith")');assert.equal(run('s.education.tracks.smith.months'),1);assert.ok(run('!!educationContact(s.education.tracks.smith.mentorId)'));assert.ok(run('s.education.tracks.smith.peerIds.length>=2'));assert.ok(run('s.skills.craft>100?true:s.skills.craft>=100'));});
test('education ranks advance at persistent month thresholds and record evaluations',()=>{const {run}=game();run(setup+'s.age=18;s.monthsRemaining=12;s.skills.craft=100;ensureEducation();s.education.tracks.smith.months=5;Math.random=()=>0;studyEducation("smith")');assert.equal(run('s.education.tracks.smith.months'),6);assert.equal(run('s.education.tracks.smith.rank'),"Temel Öğrenen");assert.equal(run('s.education.tracks.smith.evaluations'),1);assert.ok(run('s.education.tracks.smith.praise>=1'));});
test('education peers can become lasting friends through repeated bonds',()=>{const {run}=game();run(setup+'s.age=18;ensureEducation();educationPeers("story",1);window.__p=educationContact(s.education.tracks.story.peerIds[0]);__p.rel=70;__p.bonds.trust=65;s.monthsRemaining=12;educationInteraction(ensureEducation().contacts.findIndex(x=>x.id===__p.id),"befriend")');assert.ok(run('s.friends.some(x=>x.id===__p.id)'));});
test('deep education gives a career acceptance bonus without bypassing requirements',()=>{const {run}=game();run(setup+'s.age=25;ensureEducation();s.education.tracks.smith.months=60;s.education.tracks.smith.praise=3;window.__r=D.careers.find(x=>x.id==="smith");window.__b=educationFitBonusForCareer(__r)');assert.ok(run('__b>0'));assert.ok(run('__b<=.14'));run('s.skills.craft=0');assert.ok(run('careerIssue(__r).includes("Zanaat")||careerIssue(__r).includes("zanaat")||careerIssue(__r).includes("craft")'));});
test('v10 saves migrate to v13 with education profile and dedicated backup',()=>{const {run,storage}=game();run('s.version=10;delete s.education;save();load()');assert.equal(run('s.version'),13);assert.ok(storage.has('yazgi_before_v13'));assert.ok(run('s.education&&s.education.tracks&&Array.isArray(s.education.contacts)'));});
test('education mentor and peer can become direct life-event targets',()=>{const {run}=game();run(setup+'s.age=18;ensureEducation();educationMentor("smith",true);educationPeers("smith",2)');assert.ok(run('eventTargetCandidates("educationMentor").some(x=>x.statusFlags.educationTrack==="smith")'));assert.ok(run('eventTargetCandidates("educationPeer").some(x=>x.statusFlags.educationTrack==="smith")'));});
test('education life event choices improve the matching track skill and NPC bond',()=>{const {run}=game();run(setup+'s.age=18;ensureEducation();window.__m=educationMentor("smith",true);s.pendingEventId="education_mentor_trial";s.pendingEventContext={age:s.age,year:s.year+s.age,month:1,kind:"education",targetId:__m.id};window.__skill=s.skills.craft;window.__trust=__m.bonds.trust;chooseContextEvent(0)');assert.ok(run('s.skills.craft>=__skill'));assert.ok(run('__m.bonds.trust>__trust'));assert.equal(run('s.pendingEventId'),null);});
test('fresh appearance profile renders a layered portrait instead of an emoji',()=>{const {run}=game();assert.equal(run('s.version'),13);assert.ok(run('s.appearance&&APPEARANCE_OPTIONS.hair.some(x=>x.id===s.appearance.hair)'));assert.ok(run('appearanceAvatarHtml().includes("portrait-head")&&appearanceAvatarHtml().includes("portrait-hair")'));});
test('hair face and headwear customization persists without spending a month',()=>{const {run}=game();run(setup+'window.__m=s.monthsRemaining;setAppearancePart("hair","braid");setAppearancePart("face","broad");setAppearancePart("headwear","bork")');assert.equal(run('s.appearance.hair'),"braid");assert.equal(run('s.appearance.face'),"broad");assert.equal(run('s.appearance.headwear'),"bork");assert.equal(run('s.monthsRemaining'),run('__m'));});
test('appearance ages gradually and frailty can accelerate greying',()=>{const {run}=game();run(setup+'s.age=30;ensureAppearance();ensureHealthProfile();window.__young=appearanceGreyLevel();s.age=68;s.health=35;s.healthProfile.frailty=75;window.__old=appearanceGreyLevel()');assert.ok(run('__old>__young'));assert.ok(run('appearanceAvatarHtml().includes("age-elder")'));});
test('persistent health scars are rendered on the portrait',()=>{const {run}=game();run(setup+'s.age=35;addScar("battle",1,"test");addScar("fall",1,"test")');assert.equal(run('appearanceScarCount()'),2);assert.ok(run('appearanceAvatarHtml().includes("scar-1")&&appearanceAvatarHtml().includes("scar-2")'));});
test('grooming restores appearance care and consumes exactly one month',()=>{const {run}=game();run(setup+'s.age=20;s.appearance.care=25;s.monthsRemaining=12;window.__h=s.happiness;groomAppearance()');assert.equal(run('s.monthsRemaining'),11);assert.ok(run('s.appearance.care>25'));assert.ok(run('s.happiness>__h'));});
test('war headwear stays locked until military identity is earned',()=>{const {run}=game();run(setup+'s.age=20;s.role=null;s.military.served=false');assert.equal(run('appearanceChoiceAllowed("headwear","war")'),false);run('s.military.served=true');assert.equal(run('appearanceChoiceAllowed("headwear","war")'),true);});
test('v11 saves migrate to v13 with appearance profile and dedicated backup',()=>{const {run,storage}=game();run('s.version=11;delete s.appearance;save();load()');assert.equal(run('s.version'),13);assert.ok(storage.has('yazgi_before_v13'));assert.ok(run('s.appearance&&Number.isFinite(s.appearance.care)&&Array.isArray(s.appearance.history)'));});
test('meeting a partner creates a persistent relationship profile with compatibility and family approval',()=>{const {run}=game();run(setup+'s.age=20;s.monthsRemaining=12;meetPartner()');assert.ok(run('s.partner&&s.romance.current&&s.romance.current.partnerId===s.partner.id'));assert.ok(run('Number.isFinite(s.romance.current.compatibility)&&Number.isFinite(s.romance.current.familyApproval)'));});
test('relationship actions change distinct harmony commitment and tension values',()=>{const {run}=game();run(setup+'s.age=20;s.monthsRemaining=12;meetPartner();s.pendingEventId=null;s.pendingEventContext=null;window.__h=s.romance.current.harmony;window.__c=s.romance.current.commitment;relationshipAction("time");s.pendingEventId=null;s.pendingEventContext=null;relationshipAction("future")');assert.ok(run('s.romance.current.harmony>__h'));assert.ok(run('s.romance.current.commitment>__c'));});
test('family introduction raises approval and creates partner-to-kin social links',()=>{const {run}=game();run(setup+'s.age=20;s.monthsRemaining=12;meetPartner();s.pendingEventId=null;s.pendingEventContext=null;window.__a=s.romance.current.familyApproval;relationshipAction("family")');assert.ok(run('s.romance.current.familyApproval>__a'));assert.ok(run('s.parents.some(p=>!!socialLinkBetween(p,s.partner))'));});
test('marriage chance benefits from relationship depth but still uses partner requirements',()=>{const {run}=game();run(setup+'s.age=25;s.monthsRemaining=12;meetPartner();s.pendingEventId=null;s.pendingEventContext=null;s.partner.age=24;s.partner.rel=90;s.partner.bonds.trust=90;s.romance.current.commitment=95;s.romance.current.harmony=90;s.romance.current.familyApproval=90;s.romance.current.tension=0;Math.random=()=>0;marry()');assert.ok(run('s.married'));assert.equal(run('s.romance.current.stage'),"married");});
test('ending a relationship preserves the ex and archived relationship history',()=>{const {run}=game();run(setup+'s.age=24;s.monthsRemaining=12;meetPartner();s.pendingEventId=null;s.pendingEventContext=null;window.__id=s.partner.id;endRelationship()');assert.ok(run('!s.partner'));assert.ok(run('s.exPartners.some(x=>x.id===__id)'));assert.ok(run('s.romance.history.some(x=>x.partnerId===__id)'));});
test('an ex can be reconciled into a new courtship when trust is high',()=>{const {run}=game();run(setup+'s.age=24;s.monthsRemaining=12;meetPartner();s.pendingEventId=null;s.pendingEventContext=null;window.__id=s.partner.id;endRelationship();s.pendingEventId=null;s.pendingEventContext=null;s.exPartners[0].rel=90;s.exPartners[0].bonds.trust=90;s.exPartners[0].bonds.grudge=0;Math.random=()=>0;reconcileEx(0)');assert.equal(run('s.partner.id'),run('__id'));assert.equal(run('s.married'),false);assert.equal(run('s.romance.current.stage'),"courtship");});
test('neglect distance and jealousy can create transparent relationship tension',()=>{const {run}=game();run(setup+'s.age=25;meetPartner();s.pendingEventId=null;s.pendingEventContext=null;s.partner.place="Uzak Yer";window.__t=s.romance.current.tension;for(let i=0;i<6;i++)tickRomanceMonth({kind:"wait"});window.__j=s.romance.current.jealousy;tickRomanceMonth({kind:"npc",group:"friends",id:"confide"})');assert.ok(run('s.romance.current.tension>__t'));assert.ok(run('s.romance.current.jealousy>__j'));});
test('relationship crisis events target the current partner and can reduce tension',()=>{const {run}=game();run(setup+'s.age=25;meetPartner();s.pendingEventId=null;s.pendingEventContext=null;s.romance.current.tension=70;window.__p=s.partner;window.__t=s.romance.current.tension;s.pendingEventId="romance_household_strain";s.married=true;s.romance.current.stage="married";s.pendingEventContext={age:s.age,year:s.year+s.age,month:1,kind:"romance",targetId:__p.id};chooseContextEvent(0)');assert.ok(run('s.romance.current.tension<__t'));assert.equal(run('s.pendingEventId'),null);});
test('v12 saves migrate to v13 with relationship profile ex list and dedicated backup',()=>{const {run,storage}=game();run('s.version=12;delete s.romance;delete s.exPartners;save();load()');assert.equal(run('s.version'),13);assert.ok(storage.has('yazgi_before_v13'));assert.ok(run('s.romance&&Array.isArray(s.exPartners)'));});
test('postponed elder family council can return later until a real succession plan is made',()=>{const {run}=game();run(setup+'s.age=65;s.children=[normalizeNPC({name:"Heir",gender:"male",age:30,alive:true,rel:80,type:"Çocuk"})];window.__h=s.children[0];s.pendingEventId="elder_family_council";s.pendingEventContext={age:s.age,year:s.year+s.age,month:1,targetId:__h.id};chooseContextEvent(2)');assert.equal(run('s.succession.prepared'),false);assert.equal(run('s.eventHistory.includes("elder_family_council")'),false);run('s.eventCooldowns.elder_family_council=0');assert.equal(run('eventRequirementOK(EVENT_DECK.find(e=>e.id==="elder_family_council"))'),true);});
test('elder family council records a chosen heir and a persistent last wish',()=>{const {run}=game();run(setup+'s.age=65;s.children=[normalizeNPC({name:"Heir",gender:"male",age:30,alive:true,rel:80,type:"Çocuk"}),normalizeNPC({name:"Sibling",gender:"female",age:28,alive:true,rel:70,type:"Çocuk"})];window.__h=s.children[0];s.pendingEventId="elder_family_council";s.pendingEventContext={age:s.age,year:s.year+s.age,month:1,targetId:__h.id};chooseContextEvent(1)');assert.equal(run('s.will'),run('__h.id'));assert.equal(run('s.succession.prepared'),true);assert.ok(run('s.succession.familyHarmony<60'));run('s.pendingEventId="elder_last_wish";s.pendingEventContext={age:s.age,year:s.year+s.age,month:2,targetId:__h.id};chooseContextEvent(0)');assert.equal(run('s.succession.lastWish'),'Aile bir arada kalsın.');assert.ok(run('s.succession.familyHarmony>50'));});
test('death record stores cause estate and succession plan for the heir screen',()=>{const {run}=game();run(setup+'s.age=72;s.health=20;s.children=[normalizeNPC({name:"Heir",gender:"male",age:30,alive:true,rel:80,type:"Çocuk"})];s.succession={prepared:true,chosenHeirId:s.children[0].id,familyHarmony:66,lastCouncilYear:s.year+s.age,lastWish:"Aile bir arada kalsın.",elderYears:10,history:[]};s.will=s.children[0].id;s.assets=["horse","bow"];die()');assert.equal(run('s.alive'),false);assert.ok(run('s.deathRecord.cause.length>0'));assert.equal(run('s.deathRecord.chosenHeirId'),run('s.children[0].id'));assert.equal(run('s.deathRecord.assets.length'),2);assert.ok(run('s.legacy.past.at(-1).cause.length>0'));});
test('favored inheritance creates sibling tension and a delayed post-death consequence',()=>{const {run}=game();run(setup+'s.age=70;s.monthsRemaining=5;s.children=[normalizeNPC({name:"Heir",gender:"male",age:32,alive:true,rel:80,type:"Çocuk"}),normalizeNPC({name:"Sibling",gender:"female",age:30,alive:true,rel:75,type:"Çocuk"})];s.will=s.children[0].id;s.succession={prepared:true,chosenHeirId:s.children[0].id,familyHarmony:52,lastCouncilYear:s.year+s.age,lastWish:"Ailenin adı ve emeği sürdürülsün.",elderYears:12,history:[]};s.assets=["horse","bow"];window.__old=s.year+s.age;die();continueAsHeir(0)');assert.equal(run('s.year+s.age'),run('__old'));assert.equal(run('s.wealth'),100);assert.equal(run('s.assets.length'),2);assert.ok(run('s.siblings[0].bonds.grudge>=12'));assert.ok(run('s.delayedEvents.some(x=>x.eventId==="inheritance_aftershock"&&x.targetId===s.siblings[0].id&&x.status==="pending")'));});
test('legacy saves migrate to v13 with health succession economy displacement and variety profiles plus a dedicated backup',()=>{const {run,storage}=game();run('s.version=7;delete s.displacement;save();load()');assert.equal(run('s.version'),13);assert.ok(storage.has('yazgi_before_v13'));assert.ok(run('s.healthProfile&&Array.isArray(s.healthProfile.scars)'));assert.ok(run('s.succession&&Number.isFinite(s.succession.familyHarmony)'));});
